// ══════════════════════════════════════
// SVG 1 — PIRACY ZONES WORLD MAP
// ══════════════════════════════════════
function PiracyZonesSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const zones = [
    { id:"horn", icon:"🦅", color:C.red,
      label:{fr:"Corne de l'Afrique\n(Golfe d'Aden)",en:"Horn of Africa\n(Gulf of Aden)",es:"Cuerno de África\n(Golfo de Adén)",pt:"Corno de África\n(Golfo de Adém)"},
      status:{fr:"HISTORIQUEMENT CRITIQUE → Réduit depuis 2012\nOpérations : EU NavFor Atalanta · OTAN · Coalition 151",en:"HISTORICALLY CRITICAL → Reduced since 2012\nOperations: EU NavFor Atalanta · NATO · Coalition 151",es:"HISTÓRICAMENTE CRÍTICO → Reducido desde 2012\nOperaciones: EU NavFor Atalanta · OTAN · Coalición 151",pt:"HISTORICAMENTE CRÍTICO → Reduzido desde 2012\nOperações: EU NavFor Atalanta · OTAN · Coligação 151"},
      desc:{fr:"PÉRIODE CRITIQUE : 2007-2012\nPic d'attaques : 237 en 2011\nZone de prise d'otages (rançons)\nSomalie : État défaillant sans marine nationale\n\nRÉDUCTION DEPUIS 2012 :\n→ Gardes armés à bord (Best Management Practices)\n→ Opérations militaires permanentes\n→ Vitesse de transit augmentée\n→ Rançons réduites = moins rentable\n\nREDUCTION NOTABLE mais pas éliminé\nAttaques sporadiques persistent",en:"CRITICAL PERIOD: 2007-2012\nPeak attacks: 237 in 2011\nHostage-taking zone (ransoms)\nSomalia: failed state with no national navy\n\nREDUCTION SINCE 2012:\n→ Armed guards on board (Best Management Practices)\n→ Permanent military operations\n→ Increased transit speed\n→ Reduced ransoms = less profitable\n\nNOTABLE REDUCTION but not eliminated\nSporadic attacks persist",es:"PERÍODO CRÍTICO: 2007-2012\nPico de ataques: 237 en 2011\nZona de toma de rehenes (rescates)\nSomalia: Estado fallido sin marina nacional\n\nREDUCCIÓN DESDE 2012:\n→ Guardias armados a bordo (BMP)\n→ Operaciones militares permanentes\n→ Mayor velocidad de tránsito\n→ Rescates reducidos = menos rentable",pt:"PERÍODO CRÍTICO: 2007-2012\nPico de ataques: 237 em 2011\nZona de tomada de reféns (resgates)\nSomália: Estado falhado sem marinha nacional\n\nREDUÇÃO DESDE 2012:\n→ Guardas armados a bordo (BMP)\n→ Operações militares permanentes\n→ Velocidade de trânsito aumentada\n→ Resgates reduzidos = menos rentável"}},
    { id:"gulf_guinea", icon:"🐊", color:C.orange,
      label:{fr:"Golfe de Guinée\n(Afrique de l'Ouest)",en:"Gulf of Guinea\n(West Africa)",es:"Golfo de Guinea\n(África Occidental)",pt:"Golfo da Guiné\n(África Ocidental)"},
      status:{fr:"⚠️ ZONE LA PLUS DANGEREUSE ACTUELLEMENT\nNigéria · Bénin · Togo · Ghana",en:"⚠️ CURRENTLY MOST DANGEROUS ZONE\nNigeria · Benin · Togo · Ghana",es:"⚠️ ZONA MÁS PELIGROSA ACTUALMENTE\nNigeria · Benín · Togo · Ghana",pt:"⚠️ ZONA MAIS PERIGOSA ATUALMENTE\nNigéria · Benim · Togo · Gana"},
      desc:{fr:"CARACTÉRISTIQUES SPÉCIFIQUES :\n→ Enlèvements de membres d'équipage (pas de navire)\n→ Demandes de rançon plus rapides (jours vs semaines)\n→ Cibles : navires de commerce + plateformes pétrolières\n→ Pas d'opération militaire internationale permanente\n\nLIEN AVEC LE PÉTROLE :\n→ Nigeria = 1er producteur Afrique\n→ Delta du Niger = cible principale\n→ Vol de cargaisons pétrolières\n→ Pirates très organisés et bien équipés\n\nSITUATION 2024 :\nNombre d'attaques en baisse mais enlèvements persistent",en:"SPECIFIC CHARACTERISTICS:\n→ Crew member kidnappings (not vessel)\n→ Faster ransom demands (days vs weeks)\n→ Targets: merchant vessels + oil platforms\n→ No permanent international military operation\n\nLINK TO OIL:\n→ Nigeria = Africa's top producer\n→ Niger Delta = main target\n→ Oil cargo theft\n→ Well-organized and equipped pirates\n\n2024 SITUATION:\nNumber of attacks declining but kidnappings persist",es:"CARACTERÍSTICAS ESPECÍFICAS:\n→ Secuestros de tripulantes (no del buque)\n→ Peticiones de rescate más rápidas (días vs semanas)\n→ Objetivos: buques mercantes + plataformas petrolíferas\n→ Sin operación militar internacional permanente\n\nVÍNCULO CON EL PETRÓLEO:\n→ Nigeria = 1er productor de África\n→ Delta del Níger = objetivo principal\n→ Robo de cargamentos petrolíferos",pt:"CARACTERÍSTICAS ESPECÍFICAS:\n→ Sequestros de membros da tripulação (não do navio)\n→ Pedidos de resgate mais rápidos (dias vs semanas)\n→ Alvos: navios mercantes + plataformas petrolíferas\n→ Sem operação militar internacional permanente\n\nLIGAÇÃO AO PETRÓLEO:\n→ Nigéria = 1º produtor de África\n→ Delta do Níger = alvo principal\n→ Roubo de cargas petrolíferas"}},
    { id:"malacca", icon:"🐉", color:C.yellow,
      label:{fr:"Détroit de Malacca\n(Asie du Sud-Est)",en:"Strait of Malacca\n(Southeast Asia)",es:"Estrecho de Malaca\n(Sudeste Asiático)",pt:"Estreito de Malaca\n(Sudeste Asiático)"},
      status:{fr:"⚡ INCIDENTS FRÉQUENTS — Vols plutôt que piraterie",en:"⚡ FREQUENT INCIDENTS — Theft rather than piracy",es:"⚡ INCIDENTES FRECUENTES — Robos más que piratería",pt:"⚡ INCIDENTES FREQUENTES — Roubos mais que pirataria"},
      desc:{fr:"CARACTÉRISTIQUES :\n→ Principalement des vols (pas de violence)\n→ Vitesse réduite obligatoire = vulnérabilité\n→ Navires en transit sur une route OBLIGATOIRE\n→ Eaux très fréquentées (80 000+ navires/an)\n\nPAYS CONCERNÉS :\nIndonésie · Malaisie · Singapour\nPhilippines (Mer de Sulu)\n\nACTIONS RÉDUISANT LE RISQUE :\n→ Patrouilles coordonnées (MALSINDO)\n→ Partage de renseignements (ReCAAP)\n→ Vitesse de transit maximale\n\nSTATUS JURIDIQUE :\nVoler dans les eaux territoriales = vol maritime\nPAS de la piraterie (UNCLOS Art.101 = haute mer)",en:"CHARACTERISTICS:\n→ Mainly theft (no violence)\n→ Mandatory reduced speed = vulnerability\n→ Vessels in transit on MANDATORY route\n→ Very busy waters (80,000+ vessels/year)\n\nCOUNTRIES CONCERNED:\nIndonesia · Malaysia · Singapore\nPhilippines (Sulu Sea)\n\nRISK-REDUCING ACTIONS:\n→ Coordinated patrols (MALSINDO)\n→ Intelligence sharing (ReCAAP)\n→ Maximum transit speed\n\nLEGAL STATUS:\nTheft in territorial waters = maritime robbery\nNOT piracy (UNCLOS Art.101 = high seas)",es:"CARACTERÍSTICAS:\n→ Principalmente robos (sin violencia)\n→ Velocidad reducida obligatoria = vulnerabilidad\n→ Buques en tránsito por ruta OBLIGATORIA\n→ Aguas muy concurridas (+80.000 buques/año)\n\nPAÍSES AFECTADOS:\nIndonesia · Malasia · Singapur\nFilipinas (Mar de Sulú)\n\nESTATUS JURÍDICO:\nRobo en aguas territoriales = robo marítimo\nNO piratería (CONVEMAR Art.101 = alta mar)",pt:"CARACTERÍSTICAS:\n→ Principalmente roubos (sem violência)\n→ Velocidade reduzida obrigatória = vulnerabilidade\n→ Navios em trânsito por rota OBRIGATÓRIA\n→ Águas muito movimentadas (+80.000 navios/ano)\n\nPAÍSES ENVOLVIDOS:\nIndonésia · Malásia · Singapura\nFilipinas (Mar de Sulu)\n\nESTATUTO JURÍDICO:\nRoubo em águas territoriais = roubo marítimo\nNÃO pirataria (UNCLOS Art.101 = alto mar)"}},
    { id:"red_sea", icon:"⚔️", color:C.purple,
      label:{fr:"Mer Rouge\n(Houthis 2023-2024)",en:"Red Sea\n(Houthis 2023-2024)",es:"Mar Rojo\n(Huthis 2023-2024)",pt:"Mar Vermelho\n(Huthis 2023-2024)"},
      status:{fr:"🔴 ZONE DE GUERRE — PAS de piraterie classique",en:"🔴 WAR ZONE — NOT classic piracy",es:"🔴 ZONA DE GUERRA — NO piratería clásica",pt:"🔴 ZONA DE GUERRA — NÃO pirataria clássica"},
      desc:{fr:"CARACTÉRISTIQUES SPÉCIALES :\n→ Attaques par les Houthis (Yemen)\n→ Missiles · drones · attaques sous-marines\n→ Objectif politique (conflit Gaza)\n→ PAS de la piraterie (UNCLOS) = actes de GUERRE\n\nIMPACT COMMERCIAL MAJEUR :\n→ Détournement de 40% du trafic Suez\n→ Primes d'assurance ×10 (War Risk)\n→ Délais augmentés (contournement Cap de Bonne Espérance)\n→ Coût économique : milliards de dollars\n\nLÉGAL :\nRéponse militaire internationale (Operation Prosperity Guardian)\nHouthis pas reconnus comme organisation terroriste par tous les États",en:"SPECIAL CHARACTERISTICS:\n→ Houthi attacks (Yemen)\n→ Missiles · drones · underwater attacks\n→ Political objective (Gaza conflict)\n→ NOT piracy (UNCLOS) = acts of WAR\n\nMAJOR COMMERCIAL IMPACT:\n→ Diversion of 40% of Suez traffic\n→ Insurance premiums ×10 (War Risk)\n→ Increased transit times (rerouting via Cape of Good Hope)\n→ Economic cost: billions of dollars\n\nLEGAL:\nInternational military response (Operation Prosperity Guardian)\nHouthis not recognized as terrorist organization by all states",es:"CARACTERÍSTICAS ESPECIALES:\n→ Ataques de los Huthis (Yemen)\n→ Misiles · drones · ataques submarinos\n→ Objetivo político (conflicto Gaza)\n→ NO piratería (CONVEMAR) = actos de GUERRA\n\nIMPACTO COMERCIAL IMPORTANTE:\n→ Desviación del 40% del tráfico del Canal de Suez\n→ Primas de seguros ×10 (Riesgo de Guerra)\n→ Mayor tiempo de tránsito (rodeo por el Cabo de Buena Esperanza)\n\nLEGAL:\nRespuesta militar internacional (Operación Prosperity Guardian)",pt:"CARACTERÍSTICAS ESPECIAIS:\n→ Ataques dos Huthis (Iémen)\n→ Mísseis · drones · ataques submarinos\n→ Objetivo político (conflito Gaza)\n→ NÃO pirataria (UNCLOS) = atos de GUERRA\n\nIMPACTO COMERCIAL IMPORTANTE:\n→ Desvio de 40% do tráfego de Suez\n→ Prémios de seguro ×10 (Risco de Guerra)\n→ Tempos de trânsito aumentados (desvio pelo Cabo da Boa Esperança)\n\nLEGAL:\nResposta militar internacional (Operação Prosperity Guardian)"},},
  ];
  const sel_ = sel!==null ? zones[sel] : null;
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
        {zones.map((z,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)}
            style={{padding:"10px 6px",borderRadius:12,cursor:"pointer",textAlign:"center",
              background:sel===i?`${z.color}22`:"rgba(255,255,255,0.04)",
              border:`1.5px solid ${sel===i?z.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:22,marginBottom:3}}>{z.icon}</div>
            <div style={{fontSize:8,color:sel===i?z.color:C.muted,fontWeight:700,lineHeight:1.3,whiteSpace:"pre-line"}}>{z.label[lang]||z.label.fr}</div>
            <div style={{fontSize:7,color:z.color,marginTop:2,lineHeight:1.2}}>{z.status[lang]||z.status.fr}</div>
          </div>
        ))}
      </div>
      {sel_&&<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}12`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:sel_.color,marginBottom:4}}>{sel_.icon} {(sel_.label[lang]||sel_.label.fr).replace('\n',' ')}</div>
        <div style={{fontSize:10,color:sel_.color,fontWeight:700,marginBottom:6}}>{sel_.status[lang]||sel_.status.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{sel_.desc[lang]||sel_.desc.fr}</div>
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// SVG 2 — ANTI-PIRACY ACTORS
// ══════════════════════════════════════
function AntiPiracyActorsSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const actors = [
    { id:"navfor", icon:"🇪🇺", color:C.blue2,
      label:{fr:"EU NavFor Atalanta",en:"EU NavFor Atalanta",es:"EU NavFor Atalanta",pt:"EU NavFor Atalanta"},
      desc:{fr:"Opération de l'UE — lancée décembre 2008\nPremière opération navale militaire de l'UE\nZone : Golfe d'Aden · Océan Indien\n\nMANDAT :\n→ Escorter les navires vulnérables\n→ Dissuader les pirates\n→ Arrêter les pirates (si pris en flagrant)\n→ Protéger les navires humanitaires (PAM)\n\nBASE LÉGALE :\nRésolutions ONU + UNCLOS Art.100-107\n\nPROSÉCUTIONS :\nPirates transférés aux États de la région\n(Kenya · Seychelles · Mauritanie)\nSelon accords de transfert bilatéraux",en:"EU operation — launched December 2008\nFirst EU naval military operation\nZone: Gulf of Aden · Indian Ocean\n\nMANDATE:\n→ Escort vulnerable vessels\n→ Deter pirates\n→ Arrest pirates (if caught in act)\n→ Protect humanitarian vessels (WFP)\n\nLEGAL BASIS:\nUN Resolutions + UNCLOS Art.100-107\n\nPROSECUTIONS:\nPirates transferred to regional states\n(Kenya · Seychelles · Mauritania)\nUnder bilateral transfer agreements",es:"Operación de la UE — lanzada diciembre 2008\nPrimera operación naval militar de la UE\nZona: Golfo de Adén · Océano Índico\n\nMANDATO:\n→ Escoltar buques vulnerables\n→ Disuadir a los piratas\n→ Detener a los piratas (si son sorprendidos in fraganti)\n→ Proteger buques humanitarios (PMA)\n\nBASE LEGAL:\nResoluciones ONU + CONVEMAR Art.100-107",pt:"Operação da UE — lançada dezembro 2008\nPrimeira operação naval militar da UE\nZona: Golfo de Adém · Oceano Índico\n\nMANDATO:\n→ Escoltar navios vulneráveis\n→ Dissuadir os piratas\n→ Prender os piratas (se apanhados em flagrante)\n→ Proteger navios humanitários (PAM)\n\nBASE LEGAL:\nResoluções ONU + UNCLOS Art.100-107"}},
    { id:"bmp", icon:"📋", color:C.orange,
      label:{fr:"BMP — Best Management\nPractices",en:"BMP — Best Management\nPractices",es:"BMP — Mejores Prácticas\nde Gestión",pt:"BMP — Melhores Práticas\nde Gestão"},
      desc:{fr:"GUIDE INDUSTRIE ANTI-PIRATERIE\n(Version 5 actuelle)\n\nMESURES PRÉVENTIVES :\n→ Mise en place du fil barbelé (razor wire)\n→ Vitesse maximale de transit\n→ Manœuvres anti-abordage\n→ Citadelle à bord\n→ Guet permanent (équipe de quart)\n→ Veille AIS + communication UKMTO\n\nGARDES ARMÉS (PCASP) :\nPrivate Contracted Armed Security Personnel\nAutorisés par plusieurs États du pavillon\nRéducteur de risque majeur\n(0 navire avec gardes armés pris par pirates Corne d'Afrique)\n\nDÉCLARATION BMP :\nDocument à inclure dans le SMS (ISM)",en:"INDUSTRY ANTI-PIRACY GUIDE\n(Current version 5)\n\nPREVENTIVE MEASURES:\n→ Razor wire installation\n→ Maximum transit speed\n→ Anti-boarding maneuvers\n→ Citadel on board\n→ Permanent watch (watch team)\n→ AIS monitoring + UKMTO communication\n\nARMED GUARDS (PCASP):\nPrivate Contracted Armed Security Personnel\nAuthorized by several flag states\nMajor risk reducer\n(0 vessels with armed guards taken by Horn of Africa pirates)\n\nBMP DECLARATION:\nDocument to include in SMS (ISM)",es:"GUÍA ANTIPIRATERÍA DE LA INDUSTRIA\n(Versión 5 actual)\n\nMEDIDAS PREVENTIVAS:\n→ Instalación de alambre de cuchilla\n→ Velocidad máxima de tránsito\n→ Maniobras antibordaje\n→ Ciudadela a bordo\n→ Guardia permanente\n→ Vigilancia AIS + comunicación UKMTO\n\nGUARDIAS ARMADOS (PCASP):\nPersonal de seguridad armado contratado privado\nAutorizados por varios Estados de pabellón\nReductor de riesgo importante",pt:"GUIA ANTIPIRATARIA DA INDÚSTRIA\n(Versão 5 atual)\n\nMEDIDAS PREVENTIVAS:\n→ Instalação de arame farpado\n→ Velocidade máxima de trânsito\n→ Manobras anti-abordagem\n→ Cidadela a bordo\n→ Guarda permanente\n→ Vigilância AIS + comunicação UKMTO\n\nGUARDAS ARMADOS (PCASP):\nPessoal de segurança armado contratado privado\nAutorizados por vários estados de bandeira\nReductor de risco importante"}},
    { id:"recaap", icon:"🌏", color:C.teal,
      label:{fr:"ReCAAP\n(Asie-Pacifique)",en:"ReCAAP\n(Asia-Pacific)",es:"ReCAAP\n(Asia-Pacífico)",pt:"ReCAAP\n(Ásia-Pacífico)"},
      desc:{fr:"Regional Cooperation Agreement on Combating Piracy\nand Armed Robbery against Ships in Asia\n\nFondé : 2006 · Siège : Singapour\n20 États membres\n\nFONCTION :\n→ Partage d'informations sur les incidents\n→ Base de données régionale\n→ Coopération policière et judiciaire\n→ Formation des gardes-côtes\n→ Rapports statistiques mensuels\n\nLIMITE :\nCertains États majeurs absents\n(Chine · Inde · Myanmar non membres)\n\nSTATUS :\nSeule organisation intergouvernementale\ndédiée à la lutte antipiraterie en Asie",en:"Regional Cooperation Agreement on Combating Piracy\nand Armed Robbery against Ships in Asia\n\nFounded: 2006 · Headquarters: Singapore\n20 member states\n\nFUNCTION:\n→ Incident information sharing\n→ Regional database\n→ Police and judicial cooperation\n→ Coast guard training\n→ Monthly statistical reports\n\nLIMITATION:\nSome major states absent\n(China · India · Myanmar non-members)\n\nSTATUS:\nOnly intergovernmental organization\ndedicated to anti-piracy in Asia",es:"Regional Cooperation Agreement on Combating Piracy\nand Armed Robbery against Ships in Asia\n\nFundada: 2006 · Sede: Singapur\n20 Estados miembros\n\nFUNCIÓN:\n→ Intercambio de información sobre incidentes\n→ Base de datos regional\n→ Cooperación policial y judicial\n→ Formación de guardacostas\n→ Informes estadísticos mensuales",pt:"Regional Cooperation Agreement on Combating Piracy\nand Armed Robbery against Ships in Asia\n\nFundada: 2006 · Sede: Singapura\n20 estados membros\n\nFUNÇÃO:\n→ Partilha de informações sobre incidentes\n→ Base de dados regional\n→ Cooperação policial e judicial\n→ Formação dos guardas costeiros\n→ Relatórios estatísticos mensais"}},
    { id:"sua", icon:"⚖️", color:C.purple,
      label:{fr:"Convention SUA 1988\n(Terrorisme maritime)",en:"SUA Convention 1988\n(Maritime terrorism)",es:"Convenio SUA 1988\n(Terrorismo marítimo)",pt:"Convenção SUA 1988\n(Terrorismo marítimo)"},
      desc:{fr:"Convention pour la Suppression d'Actes Illicites\ncontre la Sécurité de la Navigation Maritime\n\nDIFFÉRENCE PIRATERIE vs TERRORISME :\nPiraterie (UNCLOS Art.101) = motif PRIVÉ · haute mer\nTerrorisme maritime (SUA) = motif POLITIQUE\n\nCONVENTION SUA COUVRE :\n→ Saisie d'un navire par la force\n→ Actes de violence à bord\n→ Destruction/dommage d'un navire\n→ Placement d'engins explosifs\n→ Attaques contre ports et installations\n→ Utilisation d'armes CBRN\n\nOBLIGATION :\nÉtat où le suspect est trouvé = doit\next rader ou poursuivre (aut dedere aut judicare)\n\nPROTOCOLE 2005 :\nÉtendu aux armes de destruction massive",en:"Convention for the Suppression of Unlawful Acts\nagainst the Safety of Maritime Navigation\n\nDIFFERENCE PIRACY vs TERRORISM:\nPiracy (UNCLOS Art.101) = PRIVATE motive · high seas\nMaritime terrorism (SUA) = POLITICAL motive\n\nSUA CONVENTION COVERS:\n→ Seizure of a vessel by force\n→ Acts of violence on board\n→ Vessel destruction/damage\n→ Placement of explosive devices\n→ Attacks against ports and facilities\n→ Use of CBRN weapons\n\nOBLIGATION:\nState where suspect is found = must\nextradite or prosecute (aut dedere aut judicare)\n\n2005 PROTOCOL:\nExtended to weapons of mass destruction",es:"Convenio para la Represión de Actos Ilícitos\ncontra la Seguridad de la Navegación Marítima\n\nDIFERENCIA PIRATERÍA vs TERRORISMO:\nPiratería (CONVEMAR Art.101) = motivo PRIVADO · alta mar\nTerrorismo marítimo (SUA) = motivo POLÍTICO\n\nEL CONVENIO SUA CUBRE:\n→ Aprehensión de un buque por la fuerza\n→ Actos de violencia a bordo\n→ Destrucción/daño de un buque\n→ Colocación de artefactos explosivos\n→ Ataques contra puertos e instalaciones\n→ Uso de armas QBRN\n\nOBLIGACIÓN:\nEstado donde se encuentra el sospechoso = debe\nextraditar o enjuiciar",pt:"Convenção para a Supressão de Atos Ilícitos\ncontra a Segurança da Navegação Marítima\n\nDIFERENCE PIRATARIA vs TERRORISMO:\nPirataria (UNCLOS Art.101) = motivo PRIVADO · alto mar\nTerrorismo marítimo (SUA) = motivo POLÍTICO\n\nA CONVENÇÃO SUA ABRANGE:\n→ Apreensão de um navio pela força\n→ Atos de violência a bordo\n→ Destruição/dano de um navio\n→ Colocação de engenhos explosivos\n→ Ataques contra portos e instalações\n→ Uso de armas QBRN\n\nOBRIGAÇÃO:\nEstado onde o suspeito é encontrado = deve\nextraditar ou processar"},},
  ];
  const sel_ = sel!==null ? actors[sel] : null;
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
        {actors.map((a,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)}
            style={{padding:"10px 6px",borderRadius:12,cursor:"pointer",textAlign:"center",
              background:sel===i?`${a.color}22`:"rgba(255,255,255,0.04)",
              border:`1.5px solid ${sel===i?a.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:22,marginBottom:3}}>{a.icon}</div>
            <div style={{fontSize:8,color:sel===i?a.color:C.muted,fontWeight:700,lineHeight:1.3,whiteSpace:"pre-line"}}>{a.label[lang]||a.label.fr}</div>
          </div>
        ))}
      </div>
      {sel_&&<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}12`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:sel_.color,marginBottom:6}}>{sel_.icon} {(sel_.label[lang]||sel_.label.fr).replace('\n',' ')}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{sel_.desc[lang]||sel_.desc.fr}</div>
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// SVG 3 — ISPS SECURITY LEVELS
// ══════════════════════════════════════
function ISPSLevelsSVG({ lang }) {
  const [level, setLevel] = useState(1);
  const levels = {
    1: {
      color:C.green,
      label:{fr:"NIVEAU 1 — NORMAL",en:"LEVEL 1 — NORMAL",es:"NIVEL 1 — NORMAL",pt:"NÍVEL 1 — NORMAL"},
      desc:{fr:"Mesures de sûreté MINIMALES maintenues en permanence\n\nMESURES À BORD :\n→ Contrôle d'accès de base\n→ Surveillance des zones à accès restreint\n→ Surveillance du pont et des abords\n→ Contrôle de la manutention des bagages\n→ Contrôle de la cargaison\n→ Formation ISPS régulière de l'équipage\n\nQUI DÉCIDE :\nÉtat de l'installation portuaire\n(PFSO = Port Facility Security Officer)",en:"MINIMUM security measures maintained permanently\n\nON-BOARD MEASURES:\n→ Basic access control\n→ Restricted area monitoring\n→ Deck and surroundings surveillance\n→ Baggage handling control\n→ Cargo control\n→ Regular ISPS crew training\n\nWHO DECIDES:\nPort facility state\n(PFSO = Port Facility Security Officer)",es:"Medidas de protección MÍNIMAS mantenidas permanentemente\n\nMEDIDAS A BORDO:\n→ Control de acceso básico\n→ Vigilancia de zonas de acceso restringido\n→ Vigilancia del puente y alrededores\n→ Control de la manipulación del equipaje\n→ Control de la carga\n→ Formación PBIP regular de la tripulación",pt:"Medidas de proteção MÍNIMAS mantidas permanentemente\n\nMEDIDAS A BORDO:\n→ Controlo de acesso básico\n→ Vigilância das zonas de acesso restrito\n→ Vigilância do convés e arredores\n→ Controlo da movimentação da bagagem\n→ Controlo da carga\n→ Formação ISPS regular da tripulação"},
    },
    2: {
      color:C.orange,
      label:{fr:"NIVEAU 2 — ÉLEVÉ",en:"LEVEL 2 — HEIGHTENED",es:"NIVEL 2 — ELEVADO",pt:"NÍVEL 2 — ELEVADO"},
      desc:{fr:"Risque de sûreté ACCRU — mesures supplémentaires\n\nMESURES ADDITIONNELLES :\n→ Surveillance accrue du pont\n→ Contrôle renforcé des accès\n→ Fouille partielle de la cargaison\n→ Coopération renforcée avec les autorités\n→ Communication permanente avec PFSO\n→ Équipes de quart renforcées\n→ Éclairage renforcé\n→ Préparation à la montée au niveau 3\n\nDÉCISION :\nAutorité compétente de l'État\n(Gouvernement · Garde-côtes)\nS'applique à une zone géographique",en:"INCREASED security risk — additional measures\n\nADDITIONAL MEASURES:\n→ Increased deck surveillance\n→ Enhanced access control\n→ Partial cargo search\n→ Enhanced cooperation with authorities\n→ Permanent communication with PFSO\n→ Reinforced watch teams\n→ Enhanced lighting\n→ Preparation for Level 3\n\nDECISION:\nState competent authority\n(Government · Coast Guard)\nApplies to a geographic area",es:"Riesgo de protección ELEVADO — medidas adicionales\n\nMEDIDAS ADICIONALES:\n→ Mayor vigilancia del puente\n→ Control de accesos reforzado\n→ Registro parcial de la carga\n→ Mayor cooperación con las autoridades\n→ Comunicación permanente con el OPIP\n→ Equipos de guardia reforzados\n→ Iluminación reforzada",pt:"Risco de proteção ELEVADO — medidas adicionais\n\nMEDIDAS ADICIONAIS:\n→ Vigilância aumentada do convés\n→ Controlo de acesso reforçado\n→ Pesquisa parcial da carga\n→ Cooperação reforçada com as autoridades\n→ Comunicação permanente com o OPIP\n→ Equipas de quarto reforçadas\n→ Iluminação reforçada"},
    },
    3: {
      color:C.red,
      label:{fr:"NIVEAU 3 — EXCEPTIONNEL",en:"LEVEL 3 — EXCEPTIONAL",es:"NIVEL 3 — EXCEPCIONAL",pt:"NÍVEL 3 — EXCECIONAL"},
      desc:{fr:"🔴 MENACE SPÉCIFIQUE OU IMMINENTE\n\nMESURES MAXIMALES :\n→ Arrêt de toutes les opérations cargo\n→ Évacuation partielle ou totale\n→ Fouille complète du navire\n→ Toutes entrées/sorties contrôlées\n→ Accès suspendu sauf autorisation spéciale\n→ Contact permanent avec les forces de sécurité\n→ Escorte militaire possible\n→ Isolement du navire possible\n\nDÉCISION :\nAutorité gouvernementale de HAUT NIVEAU\nOrdre signé au plus haut niveau\nDurée limitée dans le temps\n\nEXEMPLE :\nAttentat 11 septembre 2001 → Niveau 3 mondial",en:"🔴 SPECIFIC OR IMMINENT THREAT\n\nMAXIMUM MEASURES:\n→ All cargo operations stopped\n→ Partial or full evacuation\n→ Complete vessel search\n→ All entry/exit controlled\n→ Access suspended unless special authorization\n→ Permanent contact with security forces\n→ Possible military escort\n→ Vessel isolation possible\n\nDECISION:\nHIGH-LEVEL government authority\nOrder signed at highest level\nTime-limited\n\nEXAMPLE:\n9/11 attacks 2001 → Global Level 3",es:"🔴 AMENAZA ESPECÍFICA O INMINENTE\n\nMEDIDAS MÁXIMAS:\n→ Detención de todas las operaciones de carga\n→ Evacuación parcial o total\n→ Registro completo del buque\n→ Todas las entradas/salidas controladas\n→ Acceso suspendido salvo autorización especial\n→ Contacto permanente con las fuerzas de seguridad\n→ Posible escolta militar\n\nDECISIÓN:\nAutoridad gubernamental de ALTO NIVEL\nOrden firmada al más alto nivel\nDuración limitada en el tiempo",pt:"🔴 AMEAÇA ESPECÍFICA OU IMINENTE\n\nMEDIDAS MÁXIMAS:\n→ Todas as operações de carga paradas\n→ Evacuação parcial ou total\n→ Pesquisa completa do navio\n→ Todas as entradas/saídas controladas\n→ Acesso suspenso salvo autorização especial\n→ Contacto permanente com as forças de segurança\n→ Possível escolta militar\n→ Isolamento do navio possível\n\nDECISÃO:\nAutoridade governamental de ALTO NÍVEL\nOrdem assinada ao mais alto nível\nDuração limitada"},
    },
  };
  const lv = levels[level];
  return (
    <div>
      <div style={{display:"flex",gap:8,marginBottom:12}}>
        {[1,2,3].map(l=>(
          <button key={l} onClick={()=>setLevel(l)} style={{
            flex:1,padding:"10px 4px",borderRadius:12,cursor:"pointer",textAlign:"center",
            background:level===l?`${levels[l].color}22`:"rgba(255,255,255,0.04)",
            border:`2px solid ${level===l?levels[l].color:"rgba(255,255,255,0.1)"}`,
          }}>
            <div style={{fontSize:18,marginBottom:3}}>{"🟢🟡🔴"[l-1]}</div>
            <div style={{fontSize:10,fontWeight:700,color:level===l?levels[l].color:C.muted}}>
              {lang==="fr"?`Niveau ${l}`:lang==="en"?`Level ${l}`:`Nivel ${l}`}
            </div>
          </button>
        ))}
      </div>
      <div style={{padding:"14px",borderRadius:14,background:`${lv.color}12`,border:`2px solid ${lv.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:14,fontWeight:700,color:lv.color,marginBottom:10,fontFamily:"'Cinzel',serif"}}>{lv.label[lang]||lv.label.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.7,whiteSpace:"pre-line"}}>{lv.desc[lang]||lv.desc.fr}</div>
      </div>
    </div>
  );
}

