// SVG 4 — EMERGENCY PROCEDURE SIMULATOR
// ══════════════════════════════════════
function EmergencyProcedureSVG({ lang }) {
  const [step, setStep] = useState(0);
  const [active, setActive] = useState(false);

  const steps = [
    { icon:"🚨", color:C.red,
      label:{fr:"ALERTE — Pirate repéré",en:"ALERT — Pirate spotted",es:"ALERTA — Pirata avistado",pt:"ALERTA — Pirata avistado"},
      action:{fr:"IMMÉDIATEMENT :\n→ Sonner l'alarme générale (7 coups + 1 long)\n→ Capitaine sur la passerelle\n→ Accélérer au maximum\n→ Manœuvres anti-abordage (zigzag)\n→ Tout l'équipage en alerte",en:"IMMEDIATELY:\n→ Sound general alarm (7 short + 1 long)\n→ Captain to bridge\n→ Full speed ahead\n→ Anti-boarding maneuvers (zigzag)\n→ All crew on alert",es:"INMEDIATAMENTE:\n→ Sonar la alarma general (7 cortos + 1 largo)\n→ Capitán al puente\n→ Acelerar al máximo\n→ Maniobras antibordaje (zigzag)\n→ Toda la tripulación en alerta",pt:"IMEDIATAMENTE:\n→ Soar alarme geral (7 curtos + 1 longo)\n→ Capitão à ponte\n→ Velocidade máxima\n→ Manobras anti-abordagem (zigzag)\n→ Toda a tripulação em alerta"}},
    { icon:"📡", color:C.orange,
      label:{fr:"COMMUNICATION",en:"COMMUNICATION",es:"COMUNICACIÓN",pt:"COMUNICAÇÃO"},
      action:{fr:"CONTACTER :\n→ UKMTO (United Kingdom Maritime Trade Operations)\n  Numéro : +971 50 552 3215\n→ Toutes fréquences VHF 16\n→ MRCC compétent\n→ Compagnie (CSO = Company Security Officer)\n→ Armateur et P&I Club\n\nMESSAGE D'URGENCE MAYDAY si attaque",en:"CONTACT:\n→ UKMTO (United Kingdom Maritime Trade Operations)\n  Number: +971 50 552 3215\n→ All VHF 16 frequencies\n→ Competent MRCC\n→ Company (CSO = Company Security Officer)\n→ Shipowner and P&I Club\n\nMAYDAY DISTRESS MESSAGE if attack",es:"CONTACTAR:\n→ UKMTO (United Kingdom Maritime Trade Operations)\n  Número: +971 50 552 3215\n→ Todas las frecuencias VHF 16\n→ MRCC competente\n→ Compañía (OPC = Oficial de Protección de la Compañía)\n→ Armador y Club P&I\n\nMENSAJE DE SOCORRO MAYDAY si hay ataque",pt:"CONTACTAR:\n→ UKMTO (United Kingdom Maritime Trade Operations)\n  Número: +971 50 552 3215\n→ Todas as frequências VHF 16\n→ MRCC competente\n→ Companhia (CSO = Oficial de Proteção da Companhia)\n→ Armador e P&I Club\n\nMENSAGEM DE SOCORRO MAYDAY se ataque"}},
    { icon:"🏰", color:C.blue2,
      label:{fr:"CITADELLE",en:"CITADEL",es:"CIUDADELA",pt:"CIDADELA"},
      action:{fr:"SI ABORDAGE IMMINENT :\n→ Tout l'équipage en CITADELLE\n→ Verrouillage hermétique\n→ Salle des machines isolée\n→ Gouvernail mis à la bande (navire tourne en cercle)\n→ Communication radio maintenue depuis la citadelle\n→ Toutes les machines stoppées si possible\n\nCITADELLE = local fortifié avec :\nCommunications · eau · vivres · trousse médicale\nDoit résister sans ouverture jusqu'aux secours",en:"IF BOARDING IMMINENT:\n→ All crew to CITADEL\n→ Hermetic lockdown\n→ Engine room isolated\n→ Helm put hard over (vessel circles)\n→ Radio communication maintained from citadel\n→ All machinery stopped if possible\n\nCITADEL = fortified space with:\nCommunications · water · food · medical kit\nMust hold without opening until rescue",es:"SI EL ABORDAJE ES INMINENTE:\n→ Toda la tripulación a la CIUDADELA\n→ Cierre hermético\n→ Sala de máquinas aislada\n→ Timón a toda banda (el buque gira en círculo)\n→ Comunicación por radio desde la ciudadela\n→ Todas las máquinas paradas si es posible\n\nCIUDADELA = local fortificado con:\nComunicaciones · agua · alimentos · botiquín médico",pt:"SE O ABORDAMENTO FOR IMINENTE:\n→ Toda a tripulação para a CIDADELA\n→ Fecho hermético\n→ Sala de máquinas isolada\n→ Leme a todo o bordo (navio gira em círculo)\n→ Comunicação rádio mantida desde a cidadela\n→ Toda a maquinaria parada se possível\n\nCIDADELA = espaço fortificado com:\nComunicações · água · alimentos · estojo médico"}},
    { icon:"🎖️", color:C.green,
      label:{fr:"SECOURS & APRÈS",en:"RESCUE & AFTER",es:"RESCATE Y DESPUÉS",pt:"RESGATE E DEPOIS"},
      action:{fr:"LIBÉRATION :\n→ Forces militaires · rançon (si otages)\n→ Rapport IMMÉDIAT à l'armateur\n→ Rapport obligatoire à IMB (International Maritime Bureau)\n→ Rapport PSC au port suivant\n\nAPRÈS L'INCIDENT :\n→ Rapport détaillé pour les assureurs\n→ Soutien psychologique équipage\n→ Revue des procédures SSP\n→ Mise à jour du plan ISPS\n\nJURIDIQUE :\n→ Pas de responsabilité si otages libérés contre rançon\n→ P&I Club gère les réclamations\n→ War Risk : déclenchement si pertes",en:"RELEASE:\n→ Military forces · ransom (if hostages)\n→ IMMEDIATE report to shipowner\n→ Mandatory report to IMB (International Maritime Bureau)\n→ PSC report at next port\n\nAFTER THE INCIDENT:\n→ Detailed report for insurers\n→ Psychological support for crew\n→ SSP procedure review\n→ ISPS plan update\n\nLEGAL:\n→ No liability if hostages released against ransom\n→ P&I Club manages claims\n→ War Risk: activated if losses",es:"LIBERACIÓN:\n→ Fuerzas militares · rescate (si hay rehenes)\n→ Informe INMEDIATO al armador\n→ Informe obligatorio al BMI (Buró Marítimo Internacional)\n→ Informe PSC en el próximo puerto\n\nDESPUÉS DEL INCIDENTE:\n→ Informe detallado para las aseguradoras\n→ Apoyo psicológico a la tripulación\n→ Revisión de los procedimientos del PPB\n→ Actualización del plan PBIP",pt:"LIBERTAÇÃO:\n→ Forças militares · resgate (se reféns)\n→ Relatório IMEDIATO ao armador\n→ Relatório obrigatório ao IMB (Bureau Marítimo Internacional)\n→ Relatório PSC no próximo porto\n\nAPÓS O INCIDENTE:\n→ Relatório detalhado para as seguradoras\n→ Apoio psicológico à tripulação\n→ Revisão dos procedimentos do SSP\n→ Atualização do plano ISPS"},},
  ];

  const s = steps[step];
  return (
    <div>
      <div style={{display:"flex",gap:4,marginBottom:10}}>
        {steps.map((st,i)=>(
          <button key={i} onClick={()=>setStep(i)} style={{
            flex:1,padding:"6px 2px",borderRadius:8,cursor:"pointer",
            background:step===i?`${st.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${step===i?st.color:"rgba(255,255,255,0.06)"}`,
            display:"flex",flexDirection:"column",alignItems:"center",gap:2,
          }}>
            <span style={{fontSize:14}}>{st.icon}</span>
            <div style={{fontSize:6,color:step===i?st.color:C.muted,fontWeight:700}}>{i+1}</div>
          </button>
        ))}
      </div>
      <div style={{padding:"12px",borderRadius:14,background:`${s.color}12`,border:`1.5px solid ${s.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:s.color,marginBottom:8}}>{s.icon} {s.label[lang]||s.label.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.7,whiteSpace:"pre-line"}}>{s.action[lang]||s.action.fr}</div>
      </div>
      <div style={{display:"flex",gap:8,marginTop:8}}>
        <button onClick={()=>setStep(s=>Math.max(0,s-1))} disabled={step===0}
          style={{flex:1,padding:"8px",borderRadius:10,background:"rgba(255,255,255,0.06)",border:"1px solid rgba(255,255,255,0.1)",color:step===0?C.muted:C.white,cursor:step===0?"default":"pointer",fontSize:11}}>
          ◀ {lang==="fr"?"Précédent":lang==="en"?"Previous":lang==="es"?"Anterior":"Anterior"}
        </button>
        <button onClick={()=>setStep(s=>Math.min(3,s+1))} disabled={step===3}
          style={{flex:1,padding:"8px",borderRadius:10,background:step===3?"rgba(255,255,255,0.06)":`${steps[Math.min(3,step+1)].color}22`,border:`1px solid ${step===3?"rgba(255,255,255,0.1)":steps[Math.min(3,step+1)].color}`,color:C.white,cursor:step===3?"default":"pointer",fontSize:11,fontWeight:700}}>
          {lang==="fr"?"Suivant":lang==="en"?"Next":lang==="es"?"Siguiente":"Seguinte"} ▶
        </button>
      </div>
    </div>
  );
}

