export const BANK = {
  fr:[
    {q:"Qu'est-ce que l'IMB (International Maritime Bureau) et son rôle dans la lutte anti-piraterie ?",opts:["Un tribunal maritime","Organe de la CCI spécialisé dans la lutte contre la fraude maritime et la piraterie — recueille et publie les rapports d'incidents de piraterie mondiaux","Un organisme OMI","Un P&I Club"],correct:1,expl:"IMB (International Maritime Bureau) = organe de la Chambre de Commerce Internationale (ICC) créé en 1981. Rôle : recueillir les rapports d'incidents de piraterie et de vol maritime à main armée. Publier des rapports statistiques trimestriels et annuels. Le Piracy Reporting Centre (PRC) est disponible 24h/24. Les capitaines doivent OBLIGATOIREMENT signaler tout incident à l'IMB. Base de données mondiale des incidents piraterie."},
    {q:"Qu'est-ce que l'UKMTO (United Kingdom Maritime Trade Operations) ?",opts:["Un organisme douanier","Centre de coordination maritime britannique — premier contact en cas d'incident de piraterie dans l'Océan Indien et le Golfe d'Aden · numéro d'urgence","Un tribunal maritime","Un service de météo maritime"],correct:1,expl:"UKMTO = UK Maritime Trade Operations. Basé à Dubaï (UAE). Premier point de contact maritime pour les navires en transit dans la zone à risque (Golfe d'Aden, Océan Indien). Numéro d'urgence : +971 50 552 3215. Les navires doivent s'inscrire AVANT d'entrer dans la zone. En cas d'incident : appel IMMÉDIAT. Coordonne avec les forces militaires (EU NavFor, OTAN) pour les réponses d'urgence."},
    {q:"Qu'est-ce que la 'citadelle' à bord d'un navire anti-piraterie ?",opts:["Une armurerie","Local fortifié à bord permettant à l'équipage de s'y réfugier en cas d'abordage — communication radio · provisions · accès verrouillé · résistance jusqu'aux secours","Une salle de chartage","Un poste de commandement"],correct:1,expl:"Citadelle (citadel) = local fortifié préalablement désigné dans le plan de sûreté du navire (SSP). Caractéristiques : accès hermétiquement verrouillé de l'intérieur, communications radio/satellite maintenues, eau et provisions pour 24-72h, trousse médicale. En cas d'abordage imminent → tout l'équipage s'y réfugie. Le navire peut être mis sur pilote automatique. Les forces militaires peuvent intervenir plus facilement si l'équipage est regroupé et en sécurité."},
    {q:"Qu'est-ce que le PCASP (Private Contracted Armed Security Personnel) ?",opts:["Un policier maritime","Gardes armés privés embarqués sur les navires commerciaux dans les zones à risque de piraterie — autorisés par certains États du pavillon","Un militaire embarqué","Un agent douanier"],correct:1,expl:"PCASP = Personnel de sécurité armé contracté privé. Gardes armés embauchés par les armateurs pour protéger les navires dans les zones à haut risque de piraterie. Autorisés par de nombreux États du pavillon depuis 2012. Résultat : 0 navire avec PCASP à bord pris par des pirates somaliens. Règles d'engagement strictes. Assurance spéciale requise. Les armes doivent être conformes aux lois des ports d'escale. Distinction : PCASP ≠ militaires embarqués (VPD = Vessel Protection Detachments)."},
    {q:"Qu'est-ce que le VPD (Vessel Protection Detachment) ?",opts:["Un service météo naval","Équipe militaire (soldats d'un État) embarquée à bord d'un navire commercial pour protéger contre la piraterie — différent des gardes armés privés (PCASP)","Un type de bateau de patrouille","Un certificat de sécurité"],correct:1,expl:"VPD = Vessel Protection Detachment. Militaires d'un État embarqués sur navires commerciaux (souvent militaires français, néerlandais, italiens). Différent de PCASP (privés) : soldats avec toute l'autorité de l'État. Avantages : meilleur armement, règles d'engagement plus claires, immunité d'État. Inconvénients : disponibilité limitée, coût pour les armateurs. Utilisés notamment par les navires français dans l'Océan Indien."},
    {q:"Qu'est-ce que l'opération 'Ocean Shield' de l'OTAN ?",opts:["Une opération de sauvetage","Opération anti-piraterie de l'OTAN dans l'Océan Indien (2009-2016) — complémentaire à EU NavFor Atalanta","Une opération de pêche","Une mission de formation maritime"],correct:1,expl:"Operation Ocean Shield = opération anti-piraterie de l'OTAN dans le Golfe d'Aden et l'Océan Indien (2009-2016). Complémentaire à EU NavFor Atalanta. Rôle : patrouilles maritimes, escorte de navires, dissuasion pirates. Terminée en 2016 car réduction significative des attaques. La Coalition CTF-151 (Combined Task Force 151 — dirigée par USA) continue les opérations."},
    {q:"Qu'est-ce que le 'ransom' (rançon) en droit maritime de la piraterie ?",opts:["Une amende maritime","Paiement versé par l'armateur aux pirates pour libérer le navire et l'équipage — légalement ambigu · pas interdit par UNCLOS · assurance War Risk couvre parfois","Un type d'assurance","Un accord commercial"],correct:1,expl:"Rançon (ransom) = paiement fait aux pirates pour libérer un navire/équipage. Situation légale complexe : UNCLOS n'interdit pas explicitement le paiement. Certains États l'interdisent (USA). Assurance : certaines polices War Risk couvrent les rançons (K&R = Kidnap & Ransom). Résolution ONU 2018 (1838) n'interdit pas. Rançons Corne d'Afrique (2005-2012) : entre $1M et $13M par incident. Le financement des rançons a été controversé (financement du terrorisme ?)."},
    {q:"Qu'est-ce que la 'compétence universelle' en matière de piraterie maritime ?",opts:["Un droit de l'OMI","Principe selon lequel TOUT État peut arrêter, juger et condamner les pirates, quelle que soit leur nationalité ou le lieu de l'attaque — UNCLOS Art.100-107","Un droit limité aux États riverains","Un droit de l'UE uniquement"],correct:1,expl:"Compétence universelle piraterie = exception fondamentale au principe d'exclusivité du pavillon (UNCLOS Art.92). Tout État peut : saisir un navire pirate en haute mer (Art.107), arrêter les pirates, les juger selon son droit national. La piraterie est le premier exemple historique de compétence universelle en droit international. Appliquée : USA (Maersk Alabama), Pays-Bas, France, Espagne ont tous jugé des pirates somaliens."},
    {q:"Qu'est-ce que le 'transit corridor' dans le Golfe d'Aden (IRTC) ?",opts:["Un canal payant","Couloir de navigation recommandé dans le Golfe d'Aden pour les navires en transit — coordonné par EU NavFor · niveaux de sécurité plus élevés","Un accord commercial","Un couloir réservé aux militaires"],correct:1,expl:"IRTC (Internationally Recommended Transit Corridor) = couloir de navigation coordonné dans le Golfe d'Aden. Largeur : 20 milles. 2 couloirs : EST et OUEST. Coordonné par EU NavFor Atalanta. Les navires doivent : s'inscrire auprès de UKMTO avant le transit, transiter dans le corridor, maintenir les communications. Patrouilles militaires plus intenses dans le corridor. Recommandé (pas obligatoire) pour navires commerciaux."},
    {q:"Qu'est-ce que la 'zone à risque élevé' (High Risk Area - HRA) en Mer Rouge et Océan Indien ?",opts:["Une zone de pêche","Zone géographique définie par les assureurs maritimes et les MOU comme présentant un risque élevé de piraterie — primes d'assurance additionnelles","Une zone protégée","Une zone militaire"],correct:1,expl:"HRA (High Risk Area) = zone à risque élevé définie par le Joint War Committee (assureurs Lloyd's) et les autorités maritimes. Navigation dans HRA → prime d'assurance War Risk additionnelle. L'application des BMP est fortement recommandée. UKMTO doit être notifié. En 2024 : la HRA a été étendue pour inclure la Mer Rouge en raison des attaques Houthis. Impact : primes ×10 + nombreux armateurs évitent la zone."},
    {q:"Qu'est-ce que la 'resolution 1816' du Conseil de Sécurité de l'ONU sur la piraterie somalienne ?",opts:["Une résolution commerciale","Résolution ONU (2008) autorisant les États à entrer dans les eaux territoriales somaliennes pour lutter contre la piraterie — exception au principe UNCLOS","Une résolution humanitaire","Une résolution sur la pêche"],correct:1,expl:"Résolution UNSC 1816 (2008) = autorisation exceptionnelle pour les navires militaires étrangers d'entrer dans les eaux territoriales somaliennes pour lutter contre la piraterie. Exception au principe UNCLOS (mer territoriale = souveraineté). Justifiée par : État défaillant somalien incapable d'assurer la sécurité. Renouvelée annuellement. Base légale de EU NavFor, OTAN, Coalition 151 pour opérations dans les eaux somaliennes. Accord du gouvernement fédéral somalien requis."},
    {q:"Qu'est-ce que le SSP (Ship Security Plan) et qui en est responsable ?",opts:["Un plan de navigation","Plan de sûreté du navire obligatoire selon le Code ISPS — établi par le SSO (Ship Security Officer) · approuvé par l'État du pavillon","Un plan commercial","Un plan météorologique"],correct:1,expl:"SSP (Ship Security Plan / Plan de Sûreté du Navire) = document obligatoire ISPS (SOLAS XI-2). Contenu : mesures de sûreté pour chaque niveau 1/2/3, plan de la citadelle, procédures d'urgence, formation de l'équipage, communication avec PFSO. Établi par le SSO (Ship Security Officer = Officier de Sûreté du Navire). Approuvé par l'État du pavillon ou société de classification déléguée. Confidentiel. Mis à jour régulièrement."},
    {q:"Qu'est-ce que la différence entre un 'SSO', 'CSO' et 'PFSO' dans le Code ISPS ?",opts:["Ce sont les mêmes personnes","SSO = officier sûreté navire · CSO = officier sûreté compagnie · PFSO = officier sûreté installation portuaire — rôles distincts ISPS","Ce sont des titres honorifiques","Ce sont des organismes OMI"],correct:1,expl:"Triade ISPS : SSO (Ship Security Officer) = officier sûreté DU NAVIRE. Responsable du SSP à bord. CSO (Company Security Officer) = officier sûreté DE LA COMPAGNIE. Coordonne la sûreté de toute la flotte. Lien entre navire et compagnie. PFSO (Port Facility Security Officer) = officier sûreté DE L'INSTALLATION PORTUAIRE. Responsable du PFSP (Port Facility Security Plan). Coordonne avec le SSO lors des escales."},
    {q:"Qu'est-ce que la 'Djibouti Code of Conduct' (2009) ?",opts:["Un code commercial djiboutien","Accord régional de 21 États d'Afrique et d'Asie pour lutter contre la piraterie dans l'Océan Indien occidental — partage d'informations · poursuites judiciaires","Un accord douanier","Un accord de pêche"],correct:1,expl:"Djibouti Code of Conduct (2009, révisé 2017 = Jeddah Amendment) = accord régional impliquant 21 États du Golfe d'Aden, Corne de l'Afrique, Océan Indien occidental. Objectifs : partage d'informations sur la piraterie, saisie des navires pirates, poursuite des suspects, formation des gardes-côtes, soutien aux victimes. Secrétariat à Djibouti. Révision 2017 étend la portée à d'autres crimes maritimes (trafic de drogue, migration)."},
    {q:"Qu'est-ce que le 'Jack-in-a-box' (piège anti-piraterie non-létal) ?",opts:["Un jouet de bord","Dispositif non-létal de protection anti-piraterie — barrière de fil barbelé automatique · alarmes sonores et lumineuses · lances à eau à haute pression · fausse équipe de pont","Un équipement de navigation","Un système de communication"],correct:1,expl:"Mesures non-létales anti-piraterie (BMP) : 1) Razor wire (fil barbelé) = filins barbelés déployés autour du navire. 2) Alarms (alarmes sonores/lumineuses). 3) Fire hoses (lances à eau haute pression) = pour repousser les bateaux pirates. 4) Citadelle. 5) Dummy crew (silhouettes factices sur le pont) = dissuasion visuelle. 6) Evasive maneuvers. Ces mesures passives ont prouvé leur efficacité avec les BMP dans la Corne de l'Afrique."},
  ],
  en:[
    {q:"What is the IMB (International Maritime Bureau) and its role in anti-piracy?",opts:["A maritime tribunal","ICC body specializing in combating maritime fraud and piracy — collects and publishes global piracy incident reports","An IMO body","A P&I Club"],correct:1,expl:"IMB (International Maritime Bureau) = International Chamber of Commerce (ICC) body created in 1981. Role: collect piracy and armed robbery incident reports. Publish quarterly and annual statistical reports. Piracy Reporting Centre (PRC) available 24/7. Captains MUST report all incidents to IMB. Global piracy incident database."},
    {q:"What is UKMTO (United Kingdom Maritime Trade Operations)?",opts:["A customs body","British maritime coordination center — first point of contact for piracy incidents in the Indian Ocean and Gulf of Aden · emergency number","A maritime tribunal","A maritime weather service"],correct:1,expl:"UKMTO = UK Maritime Trade Operations. Based in Dubai (UAE). First maritime contact point for vessels transiting the risk zone (Gulf of Aden, Indian Ocean). Emergency number: +971 50 552 3215. Vessels must register BEFORE entering the zone. In case of incident: IMMEDIATE call. Coordinates with military forces (EU NavFor, NATO) for emergency responses."},
    {q:"What is an on-board 'citadel' in anti-piracy context?",opts:["An armory","Fortified space on board allowing crew to shelter during boarding — radio communications · provisions · locked access · holds until rescue","A chart room","A command post"],correct:1,expl:"Citadel = fortified space pre-designated in the vessel's security plan (SSP). Characteristics: hermetically locked from inside, radio/satellite communications maintained, water and provisions for 24-72h, medical kit. If imminent boarding → all crew shelter inside. Vessel can be put on autopilot. Military forces can intervene more easily if crew is grouped and safe."},
    {q:"What is PCASP (Private Contracted Armed Security Personnel)?",opts:["A maritime police officer","Private armed guards embarked on commercial vessels in piracy risk zones — authorized by certain flag states","An embarked military","A customs agent"],correct:1,expl:"PCASP = Private Contracted Armed Security Personnel. Armed guards hired by shipowners to protect vessels in high piracy risk zones. Authorized by many flag states since 2012. Result: 0 vessels with PCASP on board taken by Somali pirates. Strict rules of engagement. Special insurance required. Weapons must comply with port call laws. Distinction: PCASP ≠ military (VPD = Vessel Protection Detachments)."},
    {q:"What is a VPD (Vessel Protection Detachment)?",opts:["A naval weather service","Military team (state soldiers) embarked on a commercial vessel to protect against piracy — different from private armed guards (PCASP)","A type of patrol boat","A security certificate"],correct:1,expl:"VPD = Vessel Protection Detachment. State military personnel embarked on commercial vessels (often French, Dutch, Italian military). Different from PCASP (private): soldiers with full state authority. Advantages: better weaponry, clearer rules of engagement, state immunity. Disadvantages: limited availability, cost for shipowners. Used notably by French vessels in the Indian Ocean."},
    {q:"What is NATO's 'Ocean Shield' operation?",opts:["A rescue operation","NATO anti-piracy operation in the Indian Ocean (2009-2016) — complementary to EU NavFor Atalanta","A fishing operation","A maritime training mission"],correct:1,expl:"Operation Ocean Shield = NATO anti-piracy operation in the Gulf of Aden and Indian Ocean (2009-2016). Complementary to EU NavFor Atalanta. Role: maritime patrols, vessel escort, pirate deterrence. Ended in 2016 as attacks significantly reduced. Coalition CTF-151 (Combined Task Force 151 — US-led) continues operations."},
    {q:"What is 'ransom' in maritime piracy law?",opts:["A maritime fine","Payment made by shipowner to pirates to release vessel and crew — legally ambiguous · not prohibited by UNCLOS · War Risk insurance sometimes covers","A type of insurance","A commercial agreement"],correct:1,expl:"Ransom = payment to pirates to release vessel/crew. Complex legal situation: UNCLOS doesn't explicitly prohibit payment. Some states prohibit it (USA). Insurance: some War Risk policies cover ransoms (K&R = Kidnap & Ransom). UN Resolution 2018 (1838) doesn't prohibit. Horn of Africa ransoms (2005-2012): between $1M and $13M per incident. Ransom financing has been controversial (terrorism financing?)."},
    {q:"What is 'universal jurisdiction' in maritime piracy?",opts:["An IMO right","Principle by which ANY state can arrest, prosecute and convict pirates, regardless of their nationality or the attack location — UNCLOS Art.100-107","A right limited to coastal states","An EU-only right"],correct:1,expl:"Universal piracy jurisdiction = fundamental exception to flag state exclusivity principle (UNCLOS Art.92). Any state can: seize a pirate vessel on high seas (Art.107), arrest pirates, try them under national law. Piracy is the first historical example of universal jurisdiction in international law. Applied: USA (Maersk Alabama), Netherlands, France, Spain have all prosecuted Somali pirates."},
    {q:"What is the 'transit corridor' in the Gulf of Aden (IRTC)?",opts:["A toll canal","Recommended navigation corridor in the Gulf of Aden for transiting vessels — coordinated by EU NavFor · higher security levels","A commercial agreement","A military-only corridor"],correct:1,expl:"IRTC (Internationally Recommended Transit Corridor) = coordinated navigation corridor in the Gulf of Aden. Width: 20 miles. 2 corridors: EAST and WEST. Coordinated by EU NavFor Atalanta. Vessels must: register with UKMTO before transit, transit within corridor, maintain communications. More intense military patrols in corridor. Recommended (not mandatory) for commercial vessels."},
    {q:"What is the 'High Risk Area' (HRA) in the Red Sea and Indian Ocean?",opts:["A fishing zone","Geographic zone defined by maritime insurers and MOU as presenting high piracy risk — additional insurance premiums","A protected zone","A military zone"],correct:1,expl:"HRA (High Risk Area) = high risk zone defined by the Joint War Committee (Lloyd's insurers) and maritime authorities. Navigation in HRA → additional War Risk insurance premium. BMP application strongly recommended. UKMTO must be notified. In 2024: HRA extended to include Red Sea due to Houthi attacks. Impact: premiums ×10 + many shipowners avoid the zone."},
    {q:"What is UN Security Council 'Resolution 1816' on Somali piracy?",opts:["A commercial resolution","UN Resolution (2008) authorizing states to enter Somali territorial waters to combat piracy — exception to UNCLOS principle","A humanitarian resolution","A fishing resolution"],correct:1,expl:"UNSC Resolution 1816 (2008) = exceptional authorization for foreign military vessels to enter Somali territorial waters to combat piracy. Exception to UNCLOS (territorial sea = sovereignty). Justified by: failed Somali state unable to ensure security. Renewed annually. Legal basis for EU NavFor, NATO, Coalition 151 operations in Somali waters. Somali federal government agreement required."},
    {q:"What is the SSP (Ship Security Plan) and who is responsible for it?",opts:["A navigation plan","Mandatory vessel security plan under ISPS Code — established by SSO (Ship Security Officer) · approved by flag state","A commercial plan","A weather plan"],correct:1,expl:"SSP (Ship Security Plan) = mandatory ISPS document (SOLAS XI-2). Content: security measures for each level 1/2/3, citadel plan, emergency procedures, crew training, communication with PFSO. Established by SSO (Ship Security Officer). Approved by flag state or delegated classification society. Confidential. Regularly updated."},
    {q:"What is the difference between 'SSO', 'CSO' and 'PFSO' in the ISPS Code?",opts:["They are the same people","SSO = vessel security officer · CSO = company security officer · PFSO = port facility security officer — distinct ISPS roles","They are honorary titles","They are IMO bodies"],correct:1,expl:"ISPS triad: SSO (Ship Security Officer) = vessel security officer. Responsible for SSP on board. CSO (Company Security Officer) = company security officer. Coordinates security across the fleet. Link between vessel and company. PFSO (Port Facility Security Officer) = port facility security officer. Responsible for PFSP (Port Facility Security Plan). Coordinates with SSO during port calls."},
    {q:"What is the 'Djibouti Code of Conduct' (2009)?",opts:["A Djiboutian commercial code","Regional agreement of 21 African and Asian states to combat piracy in the Western Indian Ocean — information sharing · prosecutions","A customs agreement","A fishing agreement"],correct:1,expl:"Djibouti Code of Conduct (2009, revised 2017 = Jeddah Amendment) = regional agreement involving 21 states from Gulf of Aden, Horn of Africa, Western Indian Ocean. Objectives: piracy information sharing, seizure of pirate vessels, prosecution of suspects, coast guard training, victim support. Secretariat in Djibouti. 2017 revision extends scope to other maritime crimes (drug trafficking, migration)."},
    {q:"What are non-lethal anti-piracy measures under BMP?",opts:["Toys on board","Non-lethal protection devices — razor wire · sound/light alarms · high-pressure water hoses · dummy crew · evasive maneuvers","Navigation equipment","A communication system"],correct:1,expl:"Non-lethal anti-piracy measures (BMP): 1) Razor wire = barbed wire deployed around vessel. 2) Alarms (sound/light). 3) Fire hoses (high-pressure water) = repel pirate skiffs. 4) Citadel. 5) Dummy crew (decoy silhouettes on deck) = visual deterrence. 6) Evasive maneuvers. These passive measures have proven their effectiveness with BMP in the Horn of Africa."},
  ],
  es:[
    {q:"¿Qué es el BMI (Buró Marítimo Internacional) y su papel en la lucha antipiratería?",opts:["Un tribunal marítimo","Órgano de la CCI especializado en la lucha contra el fraude marítimo y la piratería — recoge y publica informes mundiales de incidentes de piratería","Un organismo de la OMI","Un Club P&I"],correct:1,expl:"BMI (Buró Marítimo Internacional) = órgano de la Cámara de Comercio Internacional (CCI) creado en 1981. Función: recopilar informes de incidentes de piratería y robo a mano armada. Publicar informes estadísticos trimestrales y anuales. El Centro de Notificación de Piratería (PRC) está disponible 24h/24. Los capitanes deben notificar OBLIGATORIAMENTE todo incidente al BMI."},
    {q:"¿Qué es el UKMTO (United Kingdom Maritime Trade Operations)?",opts:["Un organismo aduanero","Centro de coordinación marítima británico — primer punto de contacto en caso de incidente de piratería en el Océano Índico y el Golfo de Adén · número de urgencia","Un tribunal marítimo","Un servicio de meteorología marítima"],correct:1,expl:"UKMTO = UK Maritime Trade Operations. Con sede en Dubái (EAU). Primer punto de contacto marítimo para los buques en tránsito por la zona de riesgo. Número de urgencia: +971 50 552 3215. Los buques deben registrarse ANTES de entrar en la zona. En caso de incidente: llamada INMEDIATA. Coordina con las fuerzas militares (EU NavFor, OTAN) para las respuestas de emergencia."},
    {q:"¿Qué es la 'ciudadela' a bordo de un buque antipiratería?",opts:["Una armería","Local fortificado a bordo que permite a la tripulación refugiarse en caso de abordaje — radio · provisiones · acceso cerrado · resistencia hasta los rescatadores","Una sala de cartas","Un puesto de mando"],correct:1,expl:"Ciudadela = local fortificado previamente designado en el plan de protección del buque (PPB). Características: acceso cerrado herméticamente desde dentro, comunicaciones radio/satélite mantenidas, agua y provisiones para 24-72h, botiquín médico. En caso de abordaje inminente → toda la tripulación se refugia dentro. El buque puede ponerse en piloto automático. Las fuerzas militares pueden intervenir más fácilmente si la tripulación está agrupada y segura."},
    {q:"¿Qué es el PCASP (Personal de Seguridad Armado Contratado Privado)?",opts:["Un policía marítimo","Guardias armados privados embarcados en buques mercantes en zonas de riesgo de piratería — autorizados por ciertos Estados de pabellón","Un militar embarcado","Un agente de aduanas"],correct:1,expl:"PCASP = Personal de Seguridad Armado Contratado Privado. Guardias armados contratados por los armadores para proteger los buques en zonas de alto riesgo de piratería. Autorizados por muchos Estados de pabellón desde 2012. Resultado: 0 buques con PCASP a bordo tomados por piratas somalíes. Normas de enfrentamiento estrictas. Seguro especial necesario."},
    {q:"¿Qué es un VPD (Destacamento de Protección de Buques)?",opts:["Un servicio meteorológico naval","Equipo militar (soldados de un Estado) embarcado en un buque mercante para protegerlo de la piratería — diferente de los guardias armados privados (PCASP)","Un tipo de patrullero","Un certificado de seguridad"],correct:1,expl:"VPD = Vessel Protection Detachment (Destacamento de Protección de Buques). Militares de un Estado embarcados en buques mercantes. Diferente de PCASP (privados): soldados con toda la autoridad del Estado. Ventajas: mejor armamento, normas de enfrentamiento más claras, inmunidad estatal. Desventajas: disponibilidad limitada, coste para los armadores."},
    {q:"¿Qué es la operación 'Ocean Shield' de la OTAN?",opts:["Una operación de rescate","Operación antipiratería de la OTAN en el Océano Índico (2009-2016) — complementaria a EU NavFor Atalanta","Una operación de pesca","Una misión de formación marítima"],correct:1,expl:"Operación Ocean Shield = operación antipiratería de la OTAN en el Golfo de Adén y el Océano Índico (2009-2016). Complementaria a EU NavFor Atalanta. Función: patrullas marítimas, escolta de buques, disuasión piratas. Finalizada en 2016 por la reducción significativa de los ataques. La Coalición CTF-151 (dirigida por EE.UU.) sigue las operaciones."},
    {q:"¿Qué es el 'rescate' (ransom) en el derecho marítimo de la piratería?",opts:["Una multa marítima","Pago realizado por el armador a los piratas para liberar el buque y la tripulación — jurídicamente ambiguo · no prohibido por CONVEMAR · a veces cubierto por el seguro de guerra","Un tipo de seguro","Un acuerdo comercial"],correct:1,expl:"Rescate (ransom) = pago a piratas para liberar un buque/tripulación. Situación legal compleja: CONVEMAR no prohíbe explícitamente el pago. Algunos Estados lo prohíben (EE.UU.). Seguro: algunas pólizas de riesgo de guerra cubren los rescates (K&R = Secuestro y Rescate). Rescates Cuerno de África (2005-2012): entre $1M y $13M por incidente."},
    {q:"¿Qué es la 'competencia universal' en materia de piratería marítima?",opts:["Un derecho de la OMI","Principio según el cual CUALQUIER Estado puede detener, juzgar y condenar a los piratas, independientemente de su nacionalidad o del lugar del ataque — CONVEMAR Art.100-107","Un derecho limitado a los Estados ribereños","Un derecho solo de la UE"],correct:1,expl:"Competencia universal piratería = excepción fundamental al principio de exclusividad del pabellón. Cualquier Estado puede: apresar un buque pirata en alta mar, detener a los piratas, juzgarlos según su derecho nacional. La piratería es el primer ejemplo histórico de competencia universal en derecho internacional."},
    {q:"¿Qué es el 'corredor de tránsito' en el Golfo de Adén (IRTC)?",opts:["Un canal de peaje","Corredor de navegación recomendado en el Golfo de Adén para los buques en tránsito — coordinado por EU NavFor · mayor nivel de seguridad","Un acuerdo comercial","Un corredor reservado para militares"],correct:1,expl:"IRTC (Internationally Recommended Transit Corridor) = corredor de navegación coordinado en el Golfo de Adén. Anchura: 20 millas. 2 corredores: ESTE y OESTE. Coordinado por EU NavFor Atalanta. Los buques deben: registrarse ante el UKMTO antes del tránsito, transitar por el corredor, mantener las comunicaciones. Recomendado (no obligatorio) para buques mercantes."},
    {q:"¿Qué es la 'Zona de Alto Riesgo' (HRA) en el Mar Rojo y el Océano Índico?",opts:["Una zona de pesca","Zona geográfica definida por los aseguradores marítimos y los MOU como de alto riesgo de piratería — primas de seguros adicionales","Una zona protegida","Una zona militar"],correct:1,expl:"HRA (High Risk Area) = zona de alto riesgo definida por el Joint War Committee (aseguradores Lloyd's) y las autoridades marítimas. Navegación en HRA → prima de seguro de riesgo de guerra adicional. Se recomienda encarecidamente la aplicación de BMP. El UKMTO debe ser notificado. En 2024: la HRA se amplió para incluir el Mar Rojo debido a los ataques de los Huthis."},
    {q:"¿Qué es la 'Resolución 1816' del Consejo de Seguridad de la ONU sobre la piratería somalí?",opts:["Una resolución comercial","Resolución ONU (2008) que autoriza a los Estados a entrar en las aguas territoriales somalíes para combatir la piratería — excepción al principio CONVEMAR","Una resolución humanitaria","Una resolución sobre la pesca"],correct:1,expl:"Resolución CSNU 1816 (2008) = autorización excepcional para que los buques militares extranjeros entren en las aguas territoriales somalíes para combatir la piratería. Excepción a CONVEMAR (mar territorial = soberanía). Justificada por: Estado somalí fallido incapaz de garantizar la seguridad. Se renueva anualmente. Base legal de EU NavFor, OTAN, Coalición 151."},
    {q:"¿Qué es el PPB (Plan de Protección del Buque) y quién es responsable de él?",opts:["Un plan de navegación","Plan de protección del buque obligatorio según el Código PBIP — elaborado por el OPB (Oficial de Protección del Buque) · aprobado por el Estado de pabellón","Un plan comercial","Un plan meteorológico"],correct:1,expl:"PPB (Plan de Protección del Buque) = documento obligatorio PBIP (SOLAS XI-2). Contenido: medidas de protección para cada nivel 1/2/3, plan de ciudadela, procedimientos de emergencia, formación de la tripulación, comunicación con el OPIP. Elaborado por el OPB. Aprobado por el Estado de pabellón o sociedad de clasificación delegada. Confidencial."},
    {q:"¿Cuál es la diferencia entre 'OPB', 'OPC' y 'OPIP' en el Código PBIP?",opts:["Son las mismas personas","OPB = oficial protección buque · OPC = oficial protección compañía · OPIP = oficial protección instalación portuaria — funciones distintas PBIP","Son títulos honoríficos","Son organismos de la OMI"],correct:1,expl:"Tríada PBIP: OPB (Oficial de Protección del Buque) = oficial de protección DEL BUQUE. Responsable del PPB a bordo. OPC (Oficial de Protección de la Compañía) = oficial de protección DE LA COMPAÑÍA. Coordina la protección de toda la flota. OPIP (Oficial de Protección de la Instalación Portuaria) = oficial de protección DE LA INSTALACIÓN PORTUARIA. Responsable del PPIP."},
    {q:"¿Qué es el 'Código de Conducta de Djibouti' (2009)?",opts:["Un código comercial de Djibouti","Acuerdo regional de 21 Estados de África y Asia para combatir la piratería en el Océano Índico occidental — intercambio de información · enjuiciamientos","Un acuerdo aduanero","Un acuerdo de pesca"],correct:1,expl:"Código de Conducta de Djibouti (2009, revisado 2017 = Enmienda de Jeddah) = acuerdo regional que implica a 21 Estados del Golfo de Adén, el Cuerno de África y el Océano Índico occidental. Objetivos: intercambio de información sobre piratería, incautación de buques piratas, enjuiciamiento de sospechosos, formación de guardacostas. Secretaría en Djibouti."},
    {q:"¿Cuáles son las medidas antipiratería no letales según BMP?",opts:["Juguetes de a bordo","Dispositivos de protección no letales — alambre de cuchilla · alarmas sonoras y luminosas · mangueras de incendio a alta presión · tripulación ficticia · maniobras evasivas","Equipos de navegación","Un sistema de comunicación"],correct:1,expl:"Medidas no letales antipiratería (BMP): 1) Alambre de cuchilla = alambre de púas desplegado alrededor del buque. 2) Alarmas (sonoras/luminosas). 3) Mangueras de incendio (agua a alta presión) = repelen embarcaciones piratas. 4) Ciudadela. 5) Tripulación ficticia (siluetas en cubierta) = disuasión visual. 6) Maniobras evasivas."},
  ],
  pt:[
    {q:"O que é o IMB (Bureau Marítimo Internacional) e o seu papel na luta antipirataria?",opts:["Um tribunal marítimo","Órgão da CCI especializado no combate à fraude marítima e pirataria — recolhe e publica relatórios mundiais de incidentes de pirataria","Um organismo da IMO","Um P&I Club"],correct:1,expl:"IMB (International Maritime Bureau) = órgão da Câmara de Comércio Internacional (CCI) criado em 1981. Função: recolher relatórios de incidentes de pirataria e roubo a mão armada. Publicar relatórios estatísticos trimestrais e anuais. Centro de Notificação de Pirataria (PRC) disponível 24h/24. Os capitães devem OBRIGATORIAMENTE notificar todos os incidentes ao IMB."},
    {q:"O que é o UKMTO (United Kingdom Maritime Trade Operations)?",opts:["Um organismo aduaneiro","Centro de coordenação marítima britânico — primeiro ponto de contacto em caso de incidente de pirataria no Oceano Índico e Golfo de Adém · número de urgência","Um tribunal marítimo","Um serviço de meteorologia marítima"],correct:1,expl:"UKMTO = UK Maritime Trade Operations. Com sede no Dubai (EAU). Primeiro ponto de contacto marítimo para navios em trânsito na zona de risco. Número de urgência: +971 50 552 3215. Os navios devem registar-se ANTES de entrar na zona. Em caso de incidente: chamada IMEDIATA. Coordena com as forças militares (EU NavFor, OTAN) para respostas de emergência."},
    {q:"O que é a 'cidadela' a bordo de um navio antipirataria?",opts:["Um arsenal","Espaço fortificado a bordo que permite à tripulação refugiar-se em caso de abordagem — rádio · provisões · acesso fechado · resistência até aos socorros","Uma sala de cartas","Um posto de comando"],correct:1,expl:"Cidadela = espaço fortificado previamente designado no plano de proteção do navio (SSP). Características: acesso hermeticamente fechado por dentro, comunicações rádio/satélite mantidas, água e provisões para 24-72h, estojo médico. Em caso de abordagem iminente → toda a tripulação se refugia dentro. O navio pode ser colocado em piloto automático. As forças militares podem intervir mais facilmente se a tripulação estiver agrupada e em segurança."},
    {q:"O que é o PCASP (Pessoal de Segurança Armado Contratado Privado)?",opts:["Um polícia marítimo","Guardas armados privados embarcados em navios comerciais nas zonas de risco de pirataria — autorizados por certos estados de bandeira","Um militar embarcado","Um agente aduaneiro"],correct:1,expl:"PCASP = Pessoal de Segurança Armado Contratado Privado. Guardas armados contratados pelos armadores para proteger os navios em zonas de alto risco de pirataria. Autorizados por muitos estados de bandeira desde 2012. Resultado: 0 navios com PCASP a bordo tomados por piratas somalis. Regras de empenho rigorosas. Seguro especial necessário."},
    {q:"O que é um VPD (Destacamento de Proteção de Navios)?",opts:["Um serviço meteorológico naval","Equipa militar (soldados de um estado) embarcada num navio comercial para protegê-lo da pirataria — diferente dos guardas armados privados (PCASP)","Um tipo de patrulheiro","Um certificado de segurança"],correct:1,expl:"VPD = Vessel Protection Detachment (Destacamento de Proteção de Navios). Militares de um estado embarcados em navios comerciais. Diferente de PCASP (privados): soldados com toda a autoridade do estado. Vantagens: melhor armamento, regras de empenho mais claras, imunidade do estado. Desvantagens: disponibilidade limitada, custo para os armadores."},
    {q:"O que é a operação 'Ocean Shield' da OTAN?",opts:["Uma operação de salvamento","Operação antipirataria da OTAN no Oceano Índico (2009-2016) — complementar à EU NavFor Atalanta","Uma operação de pesca","Uma missão de formação marítima"],correct:1,expl:"Operação Ocean Shield = operação antipirataria da OTAN no Golfo de Adém e Oceano Índico (2009-2016). Complementar à EU NavFor Atalanta. Função: patrulhas marítimas, escolta de navios, dissuasão de piratas. Terminada em 2016 devido à redução significativa dos ataques. A Coligação CTF-151 (liderada pelos EUA) continua as operações."},
    {q:"O que é o 'resgate' (ransom) no direito marítimo da pirataria?",opts:["Uma multa marítima","Pagamento feito pelo armador aos piratas para libertar o navio e a tripulação — juridicamente ambíguo · não proibido pela UNCLOS · seguro de guerra às vezes cobre","Um tipo de seguro","Um acordo comercial"],correct:1,expl:"Resgate (ransom) = pagamento a piratas para libertar um navio/tripulação. Situação legal complexa: UNCLOS não proíbe explicitamente o pagamento. Alguns estados proibem-no (EUA). Seguro: algumas apólices de risco de guerra cobrem os resgates (K&R = Sequestro e Resgate). Resgates Corno de África (2005-2012): entre $1M e $13M por incidente."},
    {q:"O que é a 'competência universal' em matéria de pirataria marítima?",opts:["Um direito da IMO","Princípio pelo qual QUALQUER estado pode deter, julgar e condenar piratas, independentemente da sua nacionalidade ou do local do ataque — UNCLOS Art.100-107","Um direito limitado aos estados costeiros","Um direito apenas da UE"],correct:1,expl:"Competência universal pirataria = exceção fundamental ao princípio da exclusividade da bandeira. Qualquer estado pode: apreender um navio pirata em alto mar (Art.107), prender os piratas, julgá-los segundo o seu direito nacional. A pirataria é o primeiro exemplo histórico de competência universal no direito internacional."},
    {q:"O que é o 'corredor de trânsito' no Golfo de Adém (IRTC)?",opts:["Um canal de portagem","Corredor de navegação recomendado no Golfo de Adém para navios em trânsito — coordenado pela EU NavFor · níveis de segurança mais elevados","Um acordo comercial","Um corredor reservado a militares"],correct:1,expl:"IRTC (Internationally Recommended Transit Corridor) = corredor de navegação coordenado no Golfo de Adém. Largura: 20 milhas. 2 corredores: ESTE e OESTE. Coordenado pela EU NavFor Atalanta. Os navios devem: registar-se junto do UKMTO antes do trânsito, transitar dentro do corredor, manter as comunicações. Recomendado (não obrigatório) para navios comerciais."},
    {q:"O que é a 'Zona de Alto Risco' (HRA) no Mar Vermelho e Oceano Índico?",opts:["Uma zona de pesca","Zona geográfica definida pelos seguradores marítimos e MOU como de alto risco de pirataria — prémios de seguro adicionais","Uma zona protegida","Uma zona militar"],correct:1,expl:"HRA (High Risk Area) = zona de alto risco definida pelo Joint War Committee (seguradores Lloyd's) e autoridades marítimas. Navegação em HRA → prémio de seguro de risco de guerra adicional. Aplicação do BMP fortemente recomendada. UKMTO deve ser notificado. Em 2024: HRA alargada para incluir o Mar Vermelho devido aos ataques dos Huthis."},
    {q:"O que é a 'Resolução 1816' do Conselho de Segurança da ONU sobre a pirataria somali?",opts:["Uma resolução comercial","Resolução ONU (2008) que autoriza os estados a entrar nas águas territoriais somalis para combater a pirataria — exceção ao princípio UNCLOS","Uma resolução humanitária","Uma resolução sobre pesca"],correct:1,expl:"Resolução CSNU 1816 (2008) = autorização excecional para navios militares estrangeiros entrarem nas águas territoriais somalis para combater a pirataria. Exceção à UNCLOS (mar territorial = soberania). Justificada por: estado somali falhado incapaz de garantir a segurança. Renovada anualmente. Base legal da EU NavFor, OTAN, Coligação 151."},
    {q:"O que é o SSP (Plano de Proteção do Navio) e quem é responsável por ele?",opts:["Um plano de navegação","Plano de proteção do navio obrigatório segundo o Código ISPS — elaborado pelo OPS (Oficial de Proteção do Navio) · aprovado pelo estado de bandeira","Um plano comercial","Um plano meteorológico"],correct:1,expl:"SSP (Ship Security Plan) = documento obrigatório ISPS (SOLAS XI-2). Conteúdo: medidas de proteção para cada nível 1/2/3, plano da cidadela, procedimentos de emergência, formação da tripulação, comunicação com o OPIP. Elaborado pelo OPS (Oficial de Proteção do Navio). Aprovado pelo estado de bandeira ou sociedade de classificação delegada. Confidencial."},
    {q:"Qual é a diferença entre 'OPS', 'OPC' e 'OPIP' no Código ISPS?",opts:["São as mesmas pessoas","OPS = oficial proteção navio · OPC = oficial proteção companhia · OPIP = oficial proteção instalação portuária — funções distintas ISPS","São títulos honoríficos","São organismos da IMO"],correct:1,expl:"Tríade ISPS: OPS (Oficial de Proteção do Navio) = oficial de proteção DO NAVIO. Responsável pelo SSP a bordo. OPC (Oficial de Proteção da Companhia) = oficial de proteção DA COMPANHIA. Coordena a proteção de toda a frota. OPIP (Oficial de Proteção da Instalação Portuária) = oficial de proteção DA INSTALAÇÃO PORTUÁRIA. Responsável pelo PFSP."},
    {q:"O que é o 'Código de Conduta de Djibouti' (2009)?",opts:["Um código comercial de Djibouti","Acordo regional de 21 estados africanos e asiáticos para combater a pirataria no Oceano Índico ocidental — partilha de informações · processos judiciais","Um acordo aduaneiro","Um acordo de pesca"],correct:1,expl:"Código de Conduta de Djibouti (2009, revisto 2017 = Emenda de Jeddah) = acordo regional envolvendo 21 estados do Golfo de Adém, Corno de África, Oceano Índico ocidental. Objetivos: partilha de informações sobre pirataria, apreensão de navios piratas, processo de suspeitos, formação de guardas costeiros. Secretariado em Djibouti."},
    {q:"Quais são as medidas antipirataria não letais segundo o BMP?",opts:["Brinquedos de bordo","Dispositivos de proteção não letais — arame farpado · alarmes sonoros e luminosos · mangueiras de incêndio a alta pressão · tripulação fictícia · manobras evasivas","Equipamentos de navegação","Um sistema de comunicação"],correct:1,expl:"Medidas não letais antipirataria (BMP): 1) Arame farpado = arame farpado implantado à volta do navio. 2) Alarmes (sonoros/luminosos). 3) Mangueiras de incêndio (água a alta pressão) = repelem embarcações piratas. 4) Cidadela. 5) Tripulação fictícia (silhuetas no convés) = dissuasão visual. 6) Manobras evasivas."},
  ],
};

function QuestionBank({ lang, onComplete }) {
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [done,setDone]=useState(false);
  const questions=BANK[lang]||BANK.fr;const [shuffled]=useState(()=>questions.map(shuffleQuestionOptions));const q=shuffled[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else{setDone(true);if(onComplete)onComplete();}};
  if(done)return(<div style={{textAlign:"center",padding:"20px 0"}}><div style={{fontSize:48}}>{score>=12?"🏆":score>=8?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:20,color:C.white,margin:"8px 0 4px"}}>{score}/{questions.length}</div><div style={{fontSize:14,color:C.gold2}}>{Math.round(score/questions.length*100)}%</div></div>);
  return(<div>
    <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}><div style={{fontSize:10,color:C.muted}}>{cur+1}/{questions.length}</div><div style={{fontSize:12,color:C.gold2,fontWeight:700}}>✓ {score}</div></div>
    <div style={{height:3,background:"rgba(255,255,255,0.08)",borderRadius:3,marginBottom:12,overflow:"hidden"}}><div style={{height:"100%",width:`${(cur/questions.length)*100}%`,background:`linear-gradient(90deg,${C.red},${C.gold2})`}}/></div>
    <div style={{fontSize:13,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:12}}>{q.q}</div>
    <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
      {q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;}}return<button key={i} onClick={()=>pick(i)} style={{padding:"10px 12px",borderRadius:12,background:bg,border:`1.5px solid ${bd}`,color:C.muted,fontSize:12,textAlign:"left",cursor:answered?"default":"pointer",lineHeight:1.4}}>{opt}</button>;})}
    </div>
    {answered&&<><div style={{padding:"10px 12px",borderRadius:10,marginBottom:10,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,fontSize:11,color:C.white,lineHeight:1.6}}>{q.expl}</div>
    <button onClick={next} style={{width:"100%",padding:"11px 0",border:"none",borderRadius:12,background:`linear-gradient(135deg,${C.red},${C.gold2})`,fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?(lang==="fr"?"SUIVANT →":lang==="en"?"NEXT →":lang==="es"?"SIGUIENTE →":"PRÓXIMO →"):(lang==="fr"?"TERMINER":lang==="en"?"FINISH":lang==="es"?"TERMINAR":"TERMINAR")}</button></>}
  </div>);
}

function Stars(){const [s,setS]=useState<{x:number;y:number;sz:number;dur:number;delay:number}[]>([]);useEffect(()=>{setS(Array.from({length:16},()=>({x:Math.random()*100,y:Math.random()*100,sz:Math.random()>0.7?2:1.5,dur:2+Math.random()*4,delay:Math.random()*6})));},[]);return(<><div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:0}}>{s.map((st,i)=><div key={i} style={{position:"absolute",left:`${st.x}%`,top:`${st.y}%`,width:st.sz,height:st.sz,borderRadius:"50%",background:"white",opacity:0,animation:`tw ${st.dur}s ease-in-out ${st.delay}s infinite`}}/>)}</div><style>{`@keyframes tw{0%,100%{opacity:0}50%{opacity:0.35}}@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes correctPop{0%{transform:scale(0.85)}60%{transform:scale(1.1)}100%{transform:scale(1)}}@keyframes wrongShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}`}</style></>);}
function Card({children,style={}}){return<div style={{background:"rgba(13,31,60,0.75)",border:`1px solid ${C.border}`,borderRadius:18,padding:"16px",...style}}>{children}</div>;}
function GLine(){return<div style={{height:1,margin:"14px 0",background:`linear-gradient(90deg,transparent,${C.red}33,${C.gold2}33,transparent)`}}/>;}
function SL({icon,text,color}){return<div style={{display:"flex",alignItems:"center",gap:10,margin:"20px 0 12px"}}><span style={{fontSize:20}}>{icon}</span><div style={{fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,color:color||C.gold,letterSpacing:2}}>{text}</div><div style={{flex:1,height:1,background:`linear-gradient(90deg,${color||C.gold}44,transparent)`}}/></div>;}

function QuizComp({questions,t,onComplete}){
  const [shuffled]=useState(()=>questions.map(shuffleQuestionOptions));
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [answers,setAnswers]=useState([]);const [done,setDone]=useState(false);
  const q=shuffled[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);setAnswers(a=>[...a,{i,ok:i===q.correct}]);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else{setDone(true);onComplete(score+(isOk?1:0));}};
  if(done){const fs=score;const pct=Math.round(fs/questions.length*100);const xp=fs>=4?200:fs===3?120:60;return(<Card style={{textAlign:"center"}}><div style={{fontSize:52,marginBottom:8}}>{pct===100?"🏆":pct>=80?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:28,fontWeight:900,color:C.white,marginBottom:4}}>{fs}/{questions.length}</div><div style={{display:"inline-block",marginTop:8,padding:"6px 16px",borderRadius:20,background:"rgba(201,146,42,0.15)",border:`1px solid ${C.gold}44`,fontSize:14,color:C.gold2,fontWeight:700}}>+{xp} {t.xp} ⭐</div><GLine/><div style={{display:"flex",justifyContent:"center",gap:8,marginTop:8}}>{answers.map((a,i)=><div key={i} style={{width:32,height:32,borderRadius:"50%",background:a.ok?C.green:C.red,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,color:C.white}}>{a.ok?"✓":"✗"}</div>)}</div></Card>);}
  return(<Card style={{border:`1px solid ${C.red}33`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div style={{fontSize:11,letterSpacing:3,color:C.red,fontFamily:"'Cinzel',serif"}}>{t.quiz}</div><div style={{fontSize:12,color:C.muted}}>{t.question} {cur+1} {t.ofQ} {questions.length}</div></div><div style={{display:"flex",gap:6,marginBottom:16}}>{questions.map((_,i)=><div key={i} style={{flex:1,height:3,borderRadius:3,background:i<cur?(answers[i]?.ok?C.green:C.red):i===cur?C.red:"rgba(255,255,255,0.1)"}}/>)}</div><div style={{fontSize:14,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:16}}>{q.q}</div><div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>{q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)",anim="none";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;anim="correctPop 0.4s ease";}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;anim="wrongShake 0.4s ease";}}return<button key={i} onClick={()=>pick(i)} style={{padding:"12px 14px",borderRadius:14,background:bg,border:`1.5px solid ${bd}`,color:answered&&(i===q.correct||i===sel)?C.white:C.muted,fontSize:13,textAlign:"left",cursor:answered?"default":"pointer",animation:anim,display:"flex",alignItems:"center",gap:10,lineHeight:1.4}}><div style={{width:26,height:26,borderRadius:"50%",flexShrink:0,background:answered&&i===q.correct?C.green:answered&&i===sel?C.red:"rgba(255,255,255,0.1)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:700,color:C.white}}>{answered&&i===q.correct?"✓":answered&&i===sel?"✗":String.fromCharCode(65+i)}</div><span>{opt}</span></button>;})} </div>{answered&&<div style={{padding:"12px 14px",borderRadius:12,marginBottom:14,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,animation:"fadeUp 0.4s ease"}}><div style={{fontSize:12,fontWeight:700,marginBottom:4,color:isOk?C.green:C.red}}>{isOk?t.correct:t.wrong}</div><div style={{fontSize:11,color:C.muted,fontWeight:600,marginBottom:2}}>{t.expl}</div><div style={{fontSize:12,color:C.white,lineHeight:1.6}}>{q.expl}</div></div>}{answered&&<button onClick={next} style={{width:"100%",padding:"14px 0",border:"none",borderRadius:14,background:`linear-gradient(135deg,${C.red},${C.gold})`,fontFamily:"'Cinzel',serif",fontSize:13,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?t.next:t.finish}</button>}</Card>);
}

